function testReadStateFile(fixtureDirectory)
% Test against fixtures generated by the C++ saveStateBinary tests.
powerflow = readStateFile(fullfile(fixtureDirectory, 'powerflow.bin'));
assert(isequal(powerflow.code, 0));
assert(isequal(powerflow.index, 0));
assert(isequal(powerflow.time_ns, int64(0)));
assert(bitand(powerflow.flags, uint32(2)) == 0);
assert(~isempty(powerflow.data{1}));

diagnostic = readStateFile(fullfile(fixtureDirectory, 'solver-diagnostic.bin'));
assert(diagnostic.time(1) == 0.25);
assert(diagnostic.index(1) == 7);
assert(diagnostic.code(1) == 0);
assert(diagnostic.source(1) == 1);
assert(isequal(diagnostic.data{1}, powerflow.data{1}));
mixed = readStateFile(fullfile(fixtureDirectory, 'mixed.bin'));
assert(isequal(mixed.source, [0 1 1]));
assert(isequal(mixed.typecode, [0 0 1]));
assert(isequal(mixed.code, [0 2 1]));
assert(mixed.data{3}.row == uint32(0));
assert(mixed.data{3}.col == uint32(1));
assert(mixed.data{3}.val == 0.75);
jacStatePath = fullfile(fixtureDirectory, 'jac-state.bin');
jacState = readStateFile(jacStatePath);
assert(isequal(jacState.typecode, [0 1 2]));
assert(all(jacState.source == 1));
[state, jacobian, names] = loadJacState(jacStatePath);
assert(isequal(state, powerflow.data{1}));
assert(issparse(jacobian));
assert(isequal(size(jacobian), [numel(state) numel(state)]));
assert(numel(names) == numel(state));
jacOnly = readStateFile(fullfile(fixtureDirectory, 'jacobian.bin'));
assert(isequal(jacOnly.typecode, [1 2]));
assert(isequal(jacOnly.data{1}, jacState.data{2}));
assert(isequal(jacOnly.data{2}, names));
[jacData, jacNames] = readJacFile(fullfile(fixtureDirectory, 'jacobian.bin'));
assert(isequal(jacData, jacOnly.data{1}));
assert(isequal(jacNames, names));
solverRun = readStateFile(fullfile(fixtureDirectory, 'solver-run.bin'));
assert(all(solverRun.source == 1));
assert(all(solverRun.typecode == 0));
assert(any(solverRun.code == 0));
assert(any(solverRun.code == 2));
solverJacobian = readStateFile(fullfile(fixtureDirectory, 'solver-jacobian.bin'));
assert(all(solverJacobian.source == 1));
assert(all(solverJacobian.typecode == 1));
assert(~isempty(solverJacobian.data{1}.row));
daeRun = readStateFile(fullfile(fixtureDirectory, 'dae-solver-run.bin'));
assert(all(daeRun.source == 1));
assert(all(daeRun.typecode == 0));
assert(all(daeRun.code(1:3:end) == 0));
assert(all(daeRun.code(2:3:end) == 1));
assert(all(daeRun.code(3:3:end) == 2));
assert(isequal(daeRun.time_ns(1:3:end), daeRun.time_ns(2:3:end)));
assert(isequal(daeRun.time_ns(1:3:end), daeRun.time_ns(3:3:end)));
assert(any(daeRun.time_ns > 0));
solverNames = {'cvode', 'arkode'};
for kk = 1:numel(solverNames)
    solverPath = fullfile(fixtureDirectory, [solverNames{kk} '-solver-run.bin']);
    if exist(solverPath, 'file') == 2
        solverRun = readStateFile(solverPath);
        assert(all(solverRun.source == 1));
        assert(all(solverRun.typecode == 0));
        assert(all(solverRun.code(1:2:end) == 0));
        assert(all(solverRun.code(2:2:end) == 1));
        assert(isequal(solverRun.time_ns(1:2:end), solverRun.time_ns(2:2:end)));
        assert(any(solverRun.time_ns > 0));
    end
end

path = fullfile(fixtureDirectory, 'dynamic.bin');
dynamic = readStateFile(path);
assert(isequal(dynamic.code, [0 1 0 1]));
assert(isequal(dynamic.index, [0 0 1 1]));
assert(all(dynamic.time_ns == int64(123456789)));
assert(all(abs(dynamic.time - 0.123456789) < 1e-15));
assert(all(bitand(dynamic.flags, uint32(2)) ~= 0));
assert(all(dynamic.key == dynamic.key(1)));
n = numel(dynamic.data{1});
assert(n > 0);
assert(isequal(dynamic.data{1}, (0:n-1)' + 0.125));
assert(isequal(dynamic.data{2}, -(0:n-1)' - 0.25));
secondState = dynamic.data{1};
secondDerivative = dynamic.data{2};
secondState(1) = 123.5;
secondDerivative(1) = -456.5;
assert(isequal(dynamic.data{3}, secondState));
assert(isequal(dynamic.data{4}, secondDerivative));
[stateRows, derivRows, times] = processCVODEStatefile(path, false);
assert(isequal(stateRows, [dynamic.data{1}.'; dynamic.data{3}.']));
assert(isequal(derivRows, [dynamic.data{2}.'; dynamic.data{4}.']));
assert(isequal(times, dynamic.time([1 3])));

periodic = readStateFile(fullfile(fixtureDirectory, 'periodic.bin'));
assert(numel(periodic.code) >= 4);
assert(all(periodic.code(1:2:end) == 0));
assert(all(periodic.code(2:2:end) == 1));
assert(periodic.time_ns(end) >= int64(100000000) && ...
       periodic.time_ns(end) <= int64(150000000));

fid = fopen(path, 'rb');
assert(fid >= 0);
bytes = fread(fid, Inf, '*uint8');
fclose(fid);
badPath = [tempname(fixtureDirectory) '.bin'];
cleanup = onCleanup(@() delete(badPath)); %#ok<NASGU>
for length = 0:numel(bytes)-1
    writeBytes(badPath, bytes(1:length));
    if length == 8 + 48 + 16 * n + 4
        firstOnly = readStateFile(badPath);
        assert(isequal(firstOnly.code, [0 1]));
        continue;
    end
    expectFormatError(badPath);
end
bad = bytes;
bad(8) = uint8('2');
writeBytes(badPath, bad);
expectFormatError(badPath);
bad = bytes;
bad(49:56) = uint8(255);
writeBytes(badPath, bad);
expectFormatError(badPath);
bad = bytes;
bad(29) = bitor(bad(29), uint8(64));
writeBytes(badPath, bad);
expectFormatError(badPath);
bad = bytes;
bad(13) = uint8(2);
writeBytes(badPath, bad);
expectFormatError(badPath);
bad = bytes;
bad(17) = uint8(9);
writeBytes(badPath, bad);
expectFormatError(badPath);
fprintf('GridDyn MATLAB state reader tests passed.\n');
end

function writeBytes(path, bytes)
fid = fopen(path, 'wb');
assert(fid >= 0);
fwrite(fid, bytes, 'uint8');
fclose(fid);
end

function expectFormatError(path)
failed = false;
try
    readStateFile(path);
catch exc
    assert(strcmp(exc.identifier, 'GridDyn:StateFileFormat'));
    failed = true;
end
assert(failed);
end
